/* ==UserStyle==
@name        Roblox Floral Background
@version     1.0
@description Fondo floral para roblox.com
==/UserStyle*/

/* Keyframes fuera del bloque @-moz-document (evita errores de parseo) */
@keyframes floatBackground {
  0% { background-position: center top; }
  100% { background-position: center bottom; }
}

/* Aplica al prefijo de URL de Roblox */
@-moz-document url-prefix("https://www.roblox.com/") {
html, body { height:100%; margin:0; padding:0; }

  body {
    background-image: url('https://i.pinimg.com/1200x/49/e9/9e/49e99edbeabcc184b5c24a96d77c8544.jpg') !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    animation: floatBackground 25s ease-in-out infinite alternate !important;
  }

  /* Contenedores ligeramente translúcidos para legibilidad */
  .content, .container, #nav-content, #container-main, #navigation, .rbx-body {
    background-color: rgba(255,255,255,0.75) !important;
    border-radius: 12px !important;
  }

  /* Quitar fondos por defecto */
  #home-container, .game-home-page, .content-container {
    background: transparent !important;
  }
}
